import functools


@functools.total_ordering
class Player:
    def __init__(self, name, score):
        self.name = name
        self.score = score

    def __eq__(self, other):
        if not isinstance(other, Player):
            return NotImplemented
        return (self.score, self.name) == (other.score, other.name)

    def __lt__(self, other):
        if not isinstance(other, Player):
            return NotImplemented
        return (self.score, self.name) < (other.score, other.name)

    def __str__(self):
        return f"{self.name} {self.score}"


players = []
for _ in range(int(input())):
    name, score = input().split()
    players.append(Player(name, int(score)))

for player in sorted(players):
    print(player)
print(f"Top: {max(players)}")
print(f"Equal: {players[0] == players[1]}")
print(f"At least: {players[0] >= players[1]}")
print(f"Name match: {players[0] == players[0].name}")

