class Playlist:
    def __init__(self, name, songs):
        self.name = name
        self.songs = list(songs)

    def __len__(self):
        return len(self.songs)

    def __getitem__(self, index):
        return self.songs[index]

    def __contains__(self, title):
        return title in self.songs

    def __iter__(self):
        for song in self.songs:
            yield song


road = Playlist("Road trip", ["Drive", "Highway", "Sunset", "Home"])
print(len(road))
print(road[0], road[-1])
print(road[1:3])
print("Sunset" in road, "Rain" in road)
for i, song in enumerate(road, start=1):
    print(f"{i}. {song}")
print(bool(Playlist("Empty", [])))

