practice.solution:
class Deck:
    def __init__(self, cards):
        self.cards = cards

    def __len__(self):
        return len(self.cards)

    def __getitem__(self, index):
        return self.cards[index]

    def __contains__(self, card):
        return card in self.cards

    def __iter__(self):
        for card in self.cards:
            yield card


deck = Deck(input().split())
wanted = input().strip()

print(f"Cards: {len(deck)}")
print(f"Top: {deck[0]}")
print(f"Bottom: {deck[-1]}")
print(f"Has {wanted}: {wanted in deck}")
print(f"Hand: {' '.join(deck[:3])}")
spades = [card for card in deck if card.endswith("S")]
print(f"Spades: {' '.join(spades)}")
